SELECT COUNT(*) FROM dish


    AND dish_status = #{status}


    AND category = #{category}


    AND (dish_name LIKE CONCAT('%', #{keyword}, '%')
    OR dish_introduction LIKE CONCAT('%', #{keyword}, '%'))

SELECT dish_number, dish_name, dish_status, dish_introduction, price, category, spicy_level
FROM dish


        AND dish_status = #{request.status}


        AND category = #{request.category}


        AND (dish_name LIKE CONCAT('%', #{request.keyword}, '%')
        OR dish_introduction LIKE CONCAT('%', #{request.keyword}, '%'))


ORDER BY dish_number
LIMIT #{offset}, #{request.pageSize}

SELECT dish_number, dish_name, dish_status, dish_introduction, price, category
FROM dish
WHERE dish_number = #{dishNumber}

SELECT COUNT(*)
FROM dish
WHERE dish_number != #{dishNumber}
AND dish_name = #{dishName}

